static void run_protocol_loop(void) {
	char line[512] = { 0 };
	size_t length = 0;
	bool boot = true;
	int idle_ticks = 0;

	while (running) {
		char c = '\0';
		ssize_t bytes_read = read(serial_fd, &c, 1);
		if (bytes_read < 0) {
			if (errno == EINTR) {
				continue;
			}
			if (errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO) {
				if (boot && ++idle_ticks >= 100) {
					send_line("$BS Hello World!");
					idle_ticks = 0;
				}
				usleep(1000);
				continue;
			}
			perror("read");
			break;
		}
		if (bytes_read == 0) {
			continue;
		}
		boot = false;
		if (c == '\r') {
			continue;
		}
		if (c == '\n') {
			if (length > 0) {
				line[length] = '\0';
				char command[512];
				snprintf(command, sizeof(command), "%s", line);
				char *crc = strchr(command, '*');
				if (crc != NULL) {
					*crc = '\0';
				}
				handle_command(command, line);
				length = 0;
				line[0] = '\0';
			}
			continue;
		}
		if (length < sizeof(line) - 1) {
			line[length++] = c;
		} else {
			length = 0;
			line[0] = '\0';
		}
	}
}

int main(int argc, char *argv[]) {
	char port[256] = { 0 };

	if (!parse_args(argc, argv)) {
		return 1;
	}
	signal(SIGTERM, signal_handler);
	signal(SIGINT, signal_handler);

	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	if (options.ready_file != NULL && !serial_simulator_write_ready_file(options.ready_file, simulator_name, port)) {
		close(serial_fd);
		return 1;
	}
	if (!options.headless) {
		printf("SteelDriveII simulator ready on %s\n", port);
	}

	run_protocol_loop();
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	return 0;
}
